// runtimeRetryClock replaces the retry wait, the jitter draw and the clock: a
// wait is recorded and advances the clock instead of sleeping.
func runtimeRetryClock(t *testing.T) *[]time.Duration {
	t.Helper()
	waits := new([]time.Duration)
	now := time.Date(2026, time.March, 4, 5, 6, 7, 0, time.UTC)
	sleep, jitter, clock := retrySleep, retryJitter, retryNow
	retrySleep = func(_ context.Context, wait time.Duration) error {
		*waits = append(*waits, wait)
		now = now.Add(wait)
		return nil
	}
	retryJitter = func() float64 { return 1 }
	retryNow = func() time.Time { return now }
	t.Cleanup(func() { retrySleep, retryJitter, retryNow = sleep, jitter, clock })
	return waits
}

