// runtimeSteps answers attempt n with steps[n], the last step repeating, and
// records the host each attempt reached.
func runtimeSteps(hosts *[]string, steps ...runtimeStep) runtimeTransport {
	var index int
	return func(request *http.Request) (*http.Response, error) {
		*hosts = append(*hosts, request.URL.Host)
		step := steps[min(index, len(steps)-1)]
		index++
		if step.err != nil {
			return nil, step.err
		}
		response := runtimeResponse(step.status, `{}`)
		for i := 0; i+1 < len(step.header); i += 2 {
			response.Header.Add(step.header[i], step.header[i+1])
		}
		return response, nil
	}
}

